  margin-bottom:6px;
}
.triton-threshold-name {
  color:var(--ink);
  font-family:var(--mono);
  font-size:12px;
  font-weight:800;
}
.triton-threshold-hint {
  color:var(--ink-3);
  font-size:11px;
  line-height:1.35;
}
.triton-threshold-field .shiny-input-container {
  width:100% !important;
  margin:0 !important;
}
.triton-threshold-field input[type="text"],
.triton-threshold-field .form-control {
  width:100% !important;
  min-height:38px;
  border:1px solid var(--rule-2) !important;
  border-radius:0 !important;
  background:rgba(7,12,22,.72) !important;
  color:var(--accent) !important;
  box-shadow:none !important;
  font-family:var(--mono) !important;
  font-size:14px !important;
  font-weight:700 !important;
  padding:8px 10px !important;
}
.triton-threshold-unit {
  margin-top:4px;
  color:var(--ink-3);
  font-family:var(--mono);
  font-size:9px;
  letter-spacing:.12em;
  text-transform:uppercase;
}
.triton-more-archhead {
  display:flex;
  align-items:baseline;
  gap:8px;
  flex-wrap:wrap;
}
.triton-more-arch {
  color:var(--ink);
  font-family:var(--serif);
  font-size:20px;
  line-height:1.1;
}
.triton-threshold-static {
  border:1px solid var(--rule-2);
  background:rgba(10,16,27,.7);
  color:var(--accent);
  font-family:var(--mono);
  font-size:13px;
  padding:7px 9px;
}
@media (max-width: 1050px) {
  .triton-criteria-grid { grid-template-columns:1fr; }
}
.triton-score-track {
  margin-top:4px;
  height:4px;
  width:84px;
  background:var(--rule-2);
}
.triton-score-fill {
  height:100%;
  background:var(--accent);
}
.triton-zone-badge,
.triton-arch-tag {
  display:inline-block;
  padding:2px 7px;
  border-radius:999px;
  border:1px solid var(--rule-2);
  color:var(--ink-3);
  font-size:11px;
}
.triton-arch-tags {
  display:flex;
  gap:5px;
  flex-wrap:wrap;
}
.triton-arch-tag {
  border-color:var(--accent);
  color:var(--accent);
  font-size:10px;
  letter-spacing:.04em;
}
.triton-arch-tag.is-empty {
  border-color:transparent;
  color:var(--ink-3);
}
.triton-zone-badge.is-full,
.triton-metric.is-pass {
  border-color:#4f9d69;
  background:rgba(79,157,105,.16);
  color:#8fd6a6;
}
.triton-metric {
  display:inline-block;
  padding:2px 6px;
  border-radius:3px;
}
.triton-metric.is-miss {
  color:var(--ink-3);
}
.tracker-shell .historical-title,
.lineup-shell .historical-title {
  font-size:42px;
  margin-bottom:10px;
}
@media (max-width: 900px) {
  .historical-shell,
  .triton-shell {
    padding:18px 16px 28px;
  }
  .historical-title,
  .triton-title {
    font-size:34px;
  }
  .historical-filter-row,
  .triton-filter-row,
  .triton-filter-row--second {
    grid-template-columns:1fr;
  }
  .historical-filter-row--additional,
  .similarity-beta-grid {
    grid-template-columns:1fr;
  }
  .similarity-beta-shell {
    padding:18px 16px 28px;
  }
  .similarity-beta-topbar,
  .historical-comps-head {
    display:block;
  }
  .similarity-beta-title {
    font-size:34px;
  }
  .similarity-beta-refresh-note {
    margin-top:12px;
    white-space:normal;
  }
  .historical-filter-field,
  .historical-filter-field--slider {
    grid-column:auto;
  }
}
.body-grid { display:grid; grid-template-columns:220px 1fr; flex:1; overflow:hidden; height:100%; }
.sidebar { overflow-y:auto; border-right:1px solid var(--rule); padding:16px 14px 32px; background:var(--bg); }
.plot-area { display:flex; flex-direction:column; overflow:hidden; }
.plot-toolbar {
  display:flex; justify-content:space-between; align-items:center;
  padding:8px 18px 4px; border-bottom:1px solid var(--rule); flex-shrink:0;
}
.legend-bar { padding:6px 18px; border-bottom:1px solid var(--rule); display:flex; gap:12px; flex-shrink:0; }
.scatter-wrap { flex:1; overflow:hidden; }
.legend-item {
  display:flex; align-items:center; gap:5px;
  font-family:var(--mono); font-size:10.5px; color:var(--ink-2);
  cursor:pointer; user-select:none; transition:opacity .15s;
}
.legend-item.dim { opacity:.25; }
.swatch { width:10px; height:10px; border-radius:50%; display:inline-block; flex-shrink:0; }
.plot-meta { font-family:var(--mono); font-size:10.5px; color:var(--ink-3); }
.plot-meta .accent { color:var(--accent); }
.sidebar .form-control,
.sidebar .selectize-input,
.sidebar select {
  border:1px solid var(--rule-2) !important;
  border-radius:0 !important;
  background:var(--bg) !important;
  color:var(--ink) !important;
  font-family:var(--sans) !important;
  font-size:12.5px !important;
  box-shadow:none !important;
  padding:6px 8px !important;
}
.sidebar .selectize-input.items {
  min-height:38px !important;
  display:flex !important;
  flex-wrap:wrap !important;
  gap:4px !important;
  align-items:center !important;
}
.sidebar .selectize-input > .item {
  background:var(--accent) !important;
  color:var(--bg) !important;
  border:none !important;
  border-radius:2px !important;
  padding:2px 7px !important;
  text-shadow:none !important;
}
.sidebar .selectize-input > input { color:var(--ink) !important; }
.sidebar .selectize-dropdown {
  background:var(--bg) !important;
  border:1px solid var(--rule-2) !important;
  color:var(--ink) !important;
}
.sidebar .selectize-dropdown .option {
  color:var(--ink) !important;
  background:var(--bg) !important;
}
.sidebar .selectize-dropdown .active {
  background:var(--bg-2) !important;
  color:var(--ink) !important;
}
.sidebar .irs--shiny .irs-bar { background:var(--accent) !important; border-top:none; border-bottom:none; }
.sidebar .irs--shiny .irs-handle {
  background:var(--bg) !important;
  border:2px solid var(--accent) !important;
  border-radius:50% !important;
}
.sidebar .irs--shiny .irs-line { background:var(--rule-2) !important; border:none; }
.sidebar .irs--shiny .irs-from,
.sidebar .irs--shiny .irs-to,
.sidebar .irs--shiny .irs-single {
  background:var(--accent) !important;
  color:#0f1623 !important;
  font-family:var(--mono);
  font-size:10px;
  font-weight:700;
  border-radius:0 !important;
}
.sidebar .irs--shiny .irs-min,
.sidebar .irs--shiny .irs-max {
  font-family:var(--mono);
  font-size:9.5px;
  color:var(--ink-2);
}
.sidebar .shiny-input-container { margin-bottom:0; }
.sidebar .checkbox input[type="checkbox"] { display:none !important; }
.sidebar .checkbox label {
  display:flex !important;
  align-items:center !important;
  gap:6px !important;
  cursor:pointer;
  font-family:var(--mono) !important;
  font-size:10.5px !important;
  font-weight:400 !important;
  color:var(--ink-2) !important;
  padding:3px 2px !important;
  margin:0 !important;
  border:none !important;
  background:transparent !important;
  border-bottom:1px dotted var(--rule);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  max-width:200px;
  line-height:1.3;
  transition:color .1s;
}
.sidebar .checkbox label:hover { color:var(--ink) !important; }
.sidebar .checkbox input[type="checkbox"]:checked + span,
.sidebar .checkbox input[type="checkbox"]:checked ~ span {
  color:var(--ink) !important;
  font-weight:700 !important;
}
.sidebar .checkbox label::before {
  content:"";
  display:inline-block;
  flex-shrink:0;
  width:7px;
  height:7px;
  border-radius:50%;
  border:1px solid var(--rule-2);
  background:transparent;
  transition:background .1s, border-color .1s;
}
.sidebar .checkbox input[type="checkbox"]:checked ~ label::before,
.sidebar .checkbox:has(input:checked) label::before {
  background:var(--accent);
  border-color:var(--accent);
}
.sidebar .shiny-options-group {
  display:flex !important;
  flex-direction:column !important;
  gap:0 !important;
  flex-wrap:nowrap !important;
}
.sidebar .checkbox {
  display:block !important;
  width:100%;
  margin:0 !important;
}
.sidebar [id$="_confs"] .checkbox label {
  font-size:10px !important;
  max-width:195px !important;
}
.sidebar .tag-filter-section .checkbox label {
  align-items:flex-start !important;
  max-width:100% !important;
  white-space:normal !important;
  overflow:visible !important;
  text-overflow:clip !important;
  line-height:1.35 !important;
  padding-top:5px !important;
  padding-bottom:5px !important;
}
.sidebar .tag-filter-section .checkbox label::before { margin-top:.35em; }
.modal { position:fixed !important; inset:0 !important; z-index:1055 !important; display:none; overflow-x:hidden !important; overflow-y:auto !important; background:rgba(5,9,16,.68) !important; }
.modal.show { display:block !important; }
.modal-backdrop { position:fixed !important; inset:0 !important; z-index:1050 !important; background:rgba(5,9,16,.72) !important; }
.modal-open { overflow:hidden !important; }
.modal-dialog { max-width:1000px !important; max-height:calc(100vh - 48px) !important; margin:24px auto !important; position:relative !important; width:min(1000px, calc(100vw - 48px)) !important; pointer-events:auto !important; }
.modal-content {
  border:2px solid var(--ink) !important;
  border-radius:0 !important;
  background:var(--bg) !important;
  max-height:calc(100vh - 48px) !important;
  display:flex !important; flex-direction:column !important;
}
.modal-header { background:var(--accent) !important; border-bottom:none !important; padding:10px 18px !important; display:flex; align-items:center; }
.modal-title {
  font-family:var(--sans) !important; font-size:10px !important;
  letter-spacing:.18em !important; text-transform:uppercase !important;
  color:rgba(15,22,35,.65) !important;
}
.modal-title b { color:#0f1623 !important; margin-left:6px; }
.modal-body { padding:0 !important; min-height:0 !important; overflow:hidden !important; flex:1 1 auto !important; }
.modal-footer { display:none !important; }
.qual-note b { color:var(--ink-2); }
.stat-cell .delta.up { color:#1f6b3a; }
.stat-cell .delta.down { color:var(--accent); }
.qual-note { color:var(--ink-3); font-size:12px; line-height:1.4; margin-bottom:7px; }
.sim-metric-control .shiny-input-radiogroup { margin-bottom:8px; }
.sim-metric-control .radio-inline { margin-right:12px !important; color:var(--ink-2); font-family:var(--mono); font-size:10px; }
.div-badge {
  font-size:10px; font-weight:700; letter-spacing:.12em;
  text-transform:uppercase; border-radius:3px; padding:2px 7px;
  margin-left:6px; background:var(--bg-2); color:var(--ink-2);
  vertical-align:middle;
}
.cmp-bar .avg-mark    { position: absolute; top: -3px; bottom: -3px; width: 1px; background: var(--ink-2); }
.cmp-row .val { text-align: right; color: var(--ink); }

.bar-note { margin-top: 8px; font-size: 10px; color: var(--ink-3); line-height: 1.5; }
.bar-note b { color: var(--ink-2); }

.sim-metric-control {
  margin: -2px 0 10px;
}
.sim-metric-control .shiny-input-container {
  margin: 0 !important;
  width: 100% !important;
}
.sim-metric-control .shiny-options-group {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  align-items: center;
}
.sim-metric-control .radio,
.sim-metric-control .radio-inline {
  margin: 0 !important;
  padding: 0 !important;
}
.sim-metric-control label {
  display: inline-flex !important;
  align-items: center;
  gap: 5px;
  margin: 0 !important;
  padding: 0 !important;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.2;
  color: var(--ink-2);
  cursor: pointer;
}
.sim-metric-control input[type="radio"] {
  position: static !important;
  margin: 0 !important;
  accent-color: var(--accent);
}

.sim-row {
  display: grid; grid-template-columns: 18px 1fr auto;
  gap: 10px; align-items: center;
  border-top: 1px solid var(--rule); padding: 8px 0;
  cursor: pointer; transition: background .1s;
}
.sim-row:hover { background: var(--bg-2); }
.sim-row:last-child { border-bottom: 1px solid var(--rule); }
.sim-rank { font-family: var(--mono); font-size: 10px; color: var(--ink-3); }
.sim-main .nm   { font-family: var(--serif); font-size: 14px; font-weight: 600; line-height: 1; }
.sim-main .meta { font-size: 11px; color: var(--ink-2); margin-top: 3px; display: flex; gap: 6px; align-items: center; }
.pos-badge      { font-family: var(--mono); font-size: 9.5px; padding: 1px 5px; border: 1px solid currentColor; }
.sim-pct        { font-family: var(--serif); font-size: 18px; font-weight: 600; text-align: right; line-height: 1; }
.sim-pct .sim-lbl { font-size: 8.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--ink-3); display: block; margin-top: 2px; font-family: var(--sans); }

/* scrollbars */
::-webkit-scrollbar       { width: 6px; }
::-webkit-scrollbar-thumb { background: var(--rule-2); }
::-webkit-scrollbar-track { background: transparent; }
